svg.script:

const PROJECT_NAME = 'devel:languages:python:Factory';
const BASE_HOST = 'gitexplorer.opensuse.org';
const API_PATH = '/api/projects/devel%3Alanguages%3Apython%3AFactory/_result';
// Use same protocol as the page embedding this SVG to avoid mixed content
const API_URL = (window.location.protocol || "https:") + "//" + BASE_HOST + API_PATH;
const REFRESH_INTERVAL = 30000; // 30 seconds

function getStatusColor(status) {
    const s = status.toLowerCase();
    if (s === "reproducible") return "#44cc11";
    if (s === "unreproducible") return "#ff6600";
    if (s === "verifying") return "#007ec6";
    if (s === "succeeded") return "#28a745";
    if (s === "failed" || s === "broken" || s === "unresolvable") return "#e05d44";
    if (s === "blocked") return "#dfb317";
    if (s === "building" || s === "scheduled" || s === "dispatching" || s === "signing" || s === "finished") return "#007ec6";
    return "#9f9f9f"; // disabled, excluded, unknown
}

function getStatusIcon(status) {
    const s = status.toLowerCase();
    if (s === "reproducible") return "✓✓";
    if (s === "unreproducible") return "✓⚠";
    if (s === "verifying") return "✓⟳";
    if (s === "succeeded") return "✓";
    if (s === "failed") return "✗";
    if (s === "unresolvable") return "?";
    if (s === "broken") return "⚠";
    if (s === "blocked") return "🛑";
    if (s === "building" || s === "dispatching" || s === "signing") return "⟳";
    if (s === "scheduled") return "⏱";
    if (s === "disabled") return "○";
    if (s === "excluded") return "−";
    return "";
}

function isBuilding(status) {
    const s = status.toLowerCase();
    return s === "building" || s === "scheduled" || s === "dispatching" || s === "signing" || s === "finished";
}

function updateBadge() {
    fetch(API_URL)
        .then(response => response.text())
        .then(xmlText => {
            const parser = new DOMParser();
            const xmlDoc = parser.parseFromString(xmlText, "text/xml");
            const results = xmlDoc.querySelectorAll("result");

            // Build matrix from XML
            const matrix = {};
            let allFinal = true;

            results.forEach(result => {
                const repo = result.getAttribute("repository");
                const arch = result.getAttribute("arch");

                // Skip repositories ending with _reproduciblecheck
                if (repo && repo.endsWith("_reproduciblecheck")) {
                    return;
                }

                const dirty = result.getAttribute("dirty") === "true";
                const code = result.getAttribute("code");

                if (dirty || (code !== "published" && code !== "unpublished")) {
                    allFinal = false;
                }

                const statuses = result.querySelectorAll("status");
                statuses.forEach(status => {
                    const pkg = status.getAttribute("package");
                    const statusCode = status.getAttribute("code");
                    const reproducibleCheck = status.getAttribute("reproduciblecheck");
                    const key = `${repo}:${arch}`;

                    // Extract details from attribute or child element
                    let details = status.getAttribute("details");
                    if (!details) {
                        const detailsElem = status.querySelector("details");
                        if (detailsElem) details = detailsElem.textContent;
                    }

                    // Map status based on reproduciblecheck
                    let finalStatus = statusCode;
                    if (statusCode === "succeeded" && reproducibleCheck) {
                        if (reproducibleCheck === "succeeded") {
                            finalStatus = "reproducible";
                        } else if (reproducibleCheck === "failed") {
                            finalStatus = "unreproducible";
                        } else if (["building", "scheduled", "dispatching", "signing", "finished"].includes(reproducibleCheck)) {
                            finalStatus = "verifying";
                        }
                    }

                    // Check package status for non-final states
                    const s = finalStatus.toLowerCase();
                    const nonFinalStatuses = ["building", "scheduled", "dispatching", "signing", "finished", "blocked", "deleting", "verifying", "unreproducible"];
                    if (nonFinalStatuses.includes(s)) {
                        allFinal = false;
                    }

                    if (!matrix[pkg]) matrix[pkg] = {};
                    matrix[pkg][key] = {status: finalStatus, details: details || ""};
                });
            });

            // Update SVG elements
            const svg = document.querySelector("svg");

            // First update background rects for reproducible cells by data attributes
            const bgRects = svg.querySelectorAll("rect[data-pkg]");
            bgRects.forEach(rect => {
                const pkg = rect.getAttribute("data-pkg");
                const repo = rect.getAttribute("data-repo");
                const arch = rect.getAttribute("data-arch");
                const key = `${repo}:${arch}`;

                const entry = matrix[pkg] && matrix[pkg][key];
                if (!entry) return;

                const newStatus = entry.status;
                const newDetails = entry.details;

                // Update background color
                let color = getStatusColor(newStatus);
                if (newStatus.toLowerCase() === "finished" && newDetails) {
                    if (newDetails.toLowerCase().includes("succeeded")) {
                        color = "#44cc11";
                    } else if (newDetails.toLowerCase().includes("failed")) {
                        color = "#e05d44";
                    }
                }
                rect.setAttribute("fill", color);

                // Update animation class
                if (isBuilding(newStatus)) {
                    rect.setAttribute("class", "building-cell");
                } else {
                    rect.removeAttribute("class");
                }
            });

            // Update regular single-link cells
            const links = svg.querySelectorAll("a");
            links.forEach(link => {
                // Skip reproducibility check links (right half of split cells)
                if (link.getAttribute("data-repro") === "true") return;

                const href = link.getAttribute("href");
                if (!href || !href.includes("?log=")) return;

                // Extract repo/arch/package from log URL
                const match = href.match(/\?log=([^/]+)\/([^/]+)\/([^/]+)\//);
                if (!match) return;

                const [, repo, arch, pkg] = match;
                const key = `${decodeURIComponent(repo)}:${decodeURIComponent(arch)}`;
                const pkgName = decodeURIComponent(pkg);

                const entry = matrix[pkgName] && matrix[pkgName][key];
                if (!entry) return;

                const newStatus = entry.status;
                const newDetails = entry.details;

                // Check if this is a split cell (title indicates left half)
                const title = link.querySelector("title");
                const isSplitCellLeftHalf = title && title.textContent === "Build log";

                // For split cells, only update left icon to ✓
                if (isSplitCellLeftHalf) {
                    const text = link.querySelector("text");
                    if (text) {
                        text.textContent = "✓";
                    }
                    return;
                }

                // Update cell color for regular (non-split) cells
                const rect = link.querySelector("rect");
                if (rect) {
                    let color = getStatusColor(newStatus);
                    // Special handling for finished state based on details
                    if (newStatus.toLowerCase() === "finished" && newDetails) {
                        if (newDetails.toLowerCase().includes("succeeded")) {
                            color = "#44cc11"; // Bright green
                        } else if (newDetails.toLowerCase().includes("failed")) {
                            color = "#e05d44"; // Bright red
                        }
                    }
                    rect.setAttribute("fill", color);

                    // Update animation class
                    if (isBuilding(newStatus)) {
                        rect.setAttribute("class", "building-cell");
                    } else {
                        rect.removeAttribute("class");
                    }
                }

                // Update icon
                const text = link.querySelector("text");
                if (text) {
                    const newIcon = getStatusIcon(newStatus);
                    const animate = text.querySelector("animateTransform");

                    if (isBuilding(newStatus)) {
                        // Add animation if not present
                        if (!animate && newIcon) {
                            const x = parseFloat(text.getAttribute("x"));
                            const y = parseFloat(text.getAttribute("y"));
                            const centerY = y - 4; // Remove baseline offset
                            const animateElem = document.createElementNS("http://www.w3.org/2000/svg", "animateTransform");
                            animateElem.setAttribute("attributeName", "transform");
                            animateElem.setAttribute("type", "rotate");
                            animateElem.setAttribute("from", `0 ${x} ${centerY}`);
                            animateElem.setAttribute("to", `360 ${x} ${centerY}`);
                            animateElem.setAttribute("dur", "2s");
                            animateElem.setAttribute("repeatCount", "indefinite");
                            // Clear all children and rebuild structure
                            text.textContent = "";
                            text.appendChild(animateElem);
                            text.appendChild(document.createTextNode(newIcon));
                        } else if (animate && newIcon) {
                            // Animation exists - update only the text node, not the structure
                            // Remove all text nodes and add a single new one
                            Array.from(text.childNodes).forEach(node => {
                                if (node.nodeType === 3) node.remove();
                            });
                            text.appendChild(document.createTextNode(newIcon));
                        }
                    } else {
                        // Remove animation and show static icon
                        if (animate) animate.remove();
                        text.textContent = newIcon;
                        // Apply blocked-icon class for blocked status
                        if (newStatus.toLowerCase() === "blocked") {
                            text.setAttribute("class", "blocked-icon");
                        } else {
                            text.removeAttribute("class");
                        }
                    }
                }

                // Update tooltip
                const linkTitle = link.querySelector("title");
                if (linkTitle) {
                    const tooltipText = newDetails ? `${newStatus}: ${newDetails}` : newStatus;
                    linkTitle.textContent = tooltipText;
                }
            });

            // Update right-half icons for split cells (reproducible/unreproducible/verifying)
            const reproLinks = svg.querySelectorAll("a[data-repro=\"true\"]");
            reproLinks.forEach(link => {
                const href = link.getAttribute("href");
                if (!href || !href.includes("?log=")) return;

                // Extract repo/arch/package - need to remove _reproduciblecheck suffix from repo
                const match = href.match(/\?log=([^/]+)_reproduciblecheck\/([^/]+)\/([^/]+)\//);
                if (!match) return;

                const [, repo, arch, pkg] = match;
                const key = `${decodeURIComponent(repo)}:${decodeURIComponent(arch)}`;
                const pkgName = decodeURIComponent(pkg);

                const entry = matrix[pkgName] && matrix[pkgName][key];
                if (!entry) return;

                const newStatus = entry.status;

                // Update right icon based on status
                const text = link.querySelector("text");
                if (text) {
                    let rightIcon = "✓";
                    if (newStatus.toLowerCase() === "reproducible") {
                        rightIcon = "✓";
                    } else if (newStatus.toLowerCase() === "unreproducible") {
                        rightIcon = "⚠";
                    } else if (newStatus.toLowerCase() === "verifying") {
                        rightIcon = "⟳";
                    }
                    text.textContent = rightIcon;
                }
            });

            // Update non-clickable cells (g elements)
            const groups = svg.querySelectorAll("g");
            groups.forEach(group => {
                const rect = group.querySelector("rect");
                if (!rect) return;

                // Try to identify cell by position (simple heuristic)
                // This is for non-clickable cells that do not have log URLs
                const title = group.querySelector("title");
                if (!title) return;

                // Parse old tooltip to extract pkg/repo/arch info
                const oldTooltip = title.textContent;
                // Skip if this is a package name or repo/arch header tooltip
                if (!oldTooltip.includes(":") || oldTooltip.includes("/")) return;

                // For now, skip updating non-clickable cells
                // They are typically disabled/excluded statuses which rarely change
            });

            // Update FINAL/NOT FINAL indicator
            const statusTexts = svg.querySelectorAll("text");
            statusTexts.forEach(text => {
                if (text.textContent === "FINAL" || text.textContent === "NOT FINAL") {
                    const newText = allFinal ? "FINAL" : "NOT FINAL";
                    text.textContent = newText;

                    if (allFinal) {
                        text.removeAttribute("class");
                    } else {
                        text.setAttribute("class", "not-final-indicator");
                    }

                    // Update status row color
                    const parent = text.parentElement;
                    if (parent && parent.tagName === "a") {
                        const statusRect = parent.querySelector("rect");
                        if (statusRect) {
                            statusRect.setAttribute("fill", allFinal ? "#28a745" : "#007ec6");
                        }
                    }
                }
            });

            // Update timestamp
            const timestamp = svg.querySelector("#last-updated");
            if (timestamp) {
                const now = new Date();
                const timeStr = now.toTimeString().substring(0, 8);
                timestamp.textContent = `Updated: ${timeStr}`;
            }
        })
        .catch(err => console.error("Badge update failed:", err));
}

// Start auto-refresh
setInterval(updateBadge, REFRESH_INTERVAL);

// Update immediately when tab becomes visible again
document.addEventListener("visibilitychange", function() {
    if (!document.hidden) {
        console.log("Tab became visible, updating badge immediately");
        updateBadge();
    }
});
